// DSecServer is the server API for DSec service.
// All implementations must embed UnimplementedDSecServer
// for forward compatibility.
//
// Public API served by the apiserver, the only ingress into the cluster.
// Authenticate with metadata "authorization: Bearer <token>".
type DSecServer interface {
	CreateSandbox(context.Context, *CreateSandboxRequest) (*Sandbox, error)
	// Bulk creation for jobs that request thousands of sandboxes; one result per
	// sandbox, streamed as each completes.
	CreateSandboxes(*CreateSandboxesRequest, grpc.ServerStreamingServer[CreateSandboxResult]) error
	GetSandbox(context.Context, *SandboxRef) (*Sandbox, error)
	ListSandboxes(context.Context, *SandboxFilter) (*SandboxList, error)
	StopSandbox(context.Context, *SandboxRef) (*Sandbox, error)
	PauseSandbox(context.Context, *SandboxRef) (*Sandbox, error)
	ResumeSandbox(context.Context, *SandboxRef) (*Sandbox, error)
	TouchSandbox(context.Context, *SandboxRef) (*Sandbox, error)
	// Ends the sandbox timeout_s from now (spec §37): its ttl_max_s becomes its
	// age plus timeout_s, within the admission cap, and its idle timeout no
	// shorter. As E2B's sandbox timeout.
	SetSandboxTimeout(context.Context, *SetTimeoutRequest) (*Sandbox, error)
	ApplyTaskAction(context.Context, *TaskActionRequest) (*TaskActionResult, error)
	ClusterStatus(context.Context, *Empty) (*Snapshot, error)
	// Stop (or resume) placing sandboxes on an edge, for maintenance; its
	// sandboxes keep running. Needs project.admin on root.
	DrainEdge(context.Context, *DrainEdgeRequest) (*Empty, error)
	// IAM operations (spec §27.2), project.admin on root: back up and restore
	// the IAM state; list, add and remove Raft replicas (actor is ignored).
	BackupIAM(*IAMBackupRequest, grpc.ServerStreamingServer[BackupChunk]) error
	RestoreIAM(grpc.ClientStreamingServer[BackupChunk, Empty]) error
	IAMMembers(context.Context, *IAMMemberRequest) (*IAMMemberList, error)
	AddIAMMember(context.Context, *IAMMemberRequest) (*IAMMemberList, error)
	RemoveIAMMember(context.Context, *IAMMemberRequest) (*IAMMemberList, error)
	// Runtime operations inside a sandbox (needs sandbox.operate).
	Exec(context.Context, *ExecRequest) (*ExecResult, error)
	ExecStream(*ExecRequest, grpc.ServerStreamingServer[ExecEvent]) error
	GetOutput(context.Context, *OutputRequest) (*ExecResult, error)
	ReadFile(context.Context, *FileRequest) (*FileData, error)
	WriteFile(context.Context, *WriteFileRequest) (*FileInfo, error)
	ListDir(context.Context, *FileRequest) (*DirListing, error)
	Stat(context.Context, *FileRequest) (*FileInfo, error)
	Remove(context.Context, *FileRequest) (*Empty, error)
	Http(context.Context, *HttpRequest) (*HttpResponse, error)
	ListSessions(context.Context, *SessionRef) (*SessionList, error)
	CloseSession(context.Context, *SessionRef) (*Empty, error)
	MakeDir(context.Context, *FileRequest) (*FileInfo, error)
	Move(context.Context, *MoveRequest) (*FileInfo, error)
	// Processes (spec §37): commands run as processes of their own, outside
	// shell sessions, as E2B's envd runs them: addressed by pid (or tag), with
	// stdin, signals and an optional PTY. A stream ending does not end its
	// process; ConnectProcess attaches to a running one.
	StartProcess(*StartProcessRequest, grpc.ServerStreamingServer[ProcessEvent]) error
	ConnectProcess(*ProcessRef, grpc.ServerStreamingServer[ProcessEvent]) error
	ListProcesses(context.Context, *ProcessRef) (*ProcessList, error)
	SendProcessInput(context.Context, *ProcessInput) (*Empty, error)
	CloseProcessStdin(context.Context, *ProcessRef) (*Empty, error)
	SignalProcess(context.Context, *ProcessSignal) (*Empty, error)
	ResizeProcess(context.Context, *ProcessResize) (*Empty, error)
	// A TCP connection to a port of the sandbox (spec §37.8), as a stream: the
	// first message names the sandbox and port, then each side sends data;
	// a side done sending ends its stream (half-close).
	ConnectPort(grpc.BidiStreamingServer[PortData, PortData]) error
	// IAM management, same API for humans and agents. The actor field of each
	// request is ignored and set to the authenticated principal.
	WhoAmI(context.Context, *Empty) (*Principal, error)
	CreateProject(context.Context, *CreateProjectRequest) (*Project, error)
	CreatePrincipal(context.Context, *CreatePrincipalRequest) (*CreatePrincipalResponse, error)
	Grant(context.Context, *GrantRequest) (*Project, error)
	Revoke(context.Context, *RevokeRequest) (*Project, error)
	SetQuota(context.Context, *SetQuotaRequest) (*Project, error)
	GetProject(context.Context, *GetProjectRequest) (*Project, error)
	// Usage of a project and its subprojects per day (spec §41); needs
	// project.admin.
	GetUsage(context.Context, *UsageRequest) (*UsageReport, error)
	CreateToken(context.Context, *CreateTokenRequest) (*CreateTokenResponse, error)
	ListTokens(context.Context, *ListTokensRequest) (*TokenList, error)
	RevokeToken(context.Context, *RevokeTokenRequest) (*Empty, error)
	DeletePrincipal(context.Context, *DeletePrincipalRequest) (*Empty, error)
	DeleteProject(context.Context, *DeleteProjectRequest) (*Empty, error)
	// Shared image store (spec §17). Names are "<project>/<repo>:<tag>";
	// writes need layer.publish and reads/use need layer.use on that project.
	RegisterImage(context.Context, *RegisterImageRequest) (*ImageInfo, error)
	ComposeImage(context.Context, *ComposeImageRequest) (*ImageInfo, error)
	GetImage(context.Context, *ImageRef) (*ImageInfo, error)
	ListImages(context.Context, *ListImagesRequest) (*ImageInfoList, error)
	DeleteImage(context.Context, *ImageRef) (*Empty, error)
	// Snapshot a sandbox's writable layer as a new image on top of its own.
	PackDiff(context.Context, *PackDiffRequest) (*ImageInfo, error)
	// Snapshots and fork (spec §19). ForkSandbox copies a running sandbox into
	// count running sandboxes; the source pauses briefly and keeps its id and
	// TTLs. One result per copy, streamed as each completes.
	ForkSandbox(*ForkSandboxRequest, grpc.ServerStreamingServer[CreateSandboxResult]) error
	// Save a sandbox as an image in the store: its filesystem, and with
	// memory=true (microvm only) its memory, so new sandboxes resume from it.
	CreateSnapshot(context.Context, *CreateSnapshotRequest) (*ImageInfo, error)
	// Change a running sandbox's network rules (spec §20). Needs
	// sandbox.operate; denials apply to new connections at once.
	UpdateNetwork(context.Context, *UpdateNetworkRequest) (*Sandbox, error)
	mustEmbedUnimplementedDSecServer()
}

